18	// Vote records a weighted vote against an open proposal.
19	func Vote(proposal *Proposal, weight int64, support bool) error {
20		if proposal.State != "voting" {
21			return errInvalid("proposal is not open for voting")
22		}
23		if weight <= 0 {
24			return errInvalid("vote weight must be positive")
25		}
26		if support {
27			proposal.ForVotes += weight
28		} else {
29			proposal.AgainstVotes += weight
30		}
31		return nil
32	}
33	
