371	func assertMemberViews(t *testing.T, prefix string, got, want map[string]MemberView) {
372		t.Helper()
373		if len(got) != len(want) {
374			t.Fatalf("%s: member count=%d want %d", prefix, len(got), len(want))
375		}
376		for id, w := range want {
377			g, ok := got[id]
378			if !ok {
379				t.Errorf("%s: member %s missing from view", prefix, id)
380				continue
381			}
382			if !equalStrings(g.Path, w.Path) {
383				t.Errorf("%s: member %s path=%v want %v", prefix, id, g.Path, w.Path)
384			}
385			// 路径的相邻成员必须对应一次真实委托；无重复成员；首尾为本人和最终代表。
386			if len(g.Path) == 0 || g.Path[0] != id || g.Path[len(g.Path)-1] != g.Delegate {
387				t.Errorf("%s: member %s path %v inconsistent with self/final representative %q", prefix, id, g.Path, g.Delegate)
388			}
389			if g.Delegate != w.Delegate {
390				t.Errorf("%s: member %s delegate=%q want %q", prefix, id, g.Delegate, w.Delegate)
391			}
392			if g.Direct != w.Direct {
393				t.Errorf("%s: member %s direct_to=%q want %q", prefix, id, g.Direct, w.Direct)
394			}
395			if g.Weight != w.Weight {
396				t.Errorf("%s: member %s weight=%d want %d", prefix, id, g.Weight, w.Weight)
397			}
398		}
399	}
