609			t.Fatalf("execute before timelock: %v", err)
610		}
611		rcpt, err := store.Execute("gip-exec", 300)
612		if err != nil {
613			t.Fatalf("execute passed vote proposal: %v", err)
614		}
615		if rcpt.ExecutedAt != 300 || len(rcpt.Actions) != 1 {
616			t.Fatalf("bad receipt: %+v", rcpt)
617		}
618		if bal, _ := store.TreasuryBalance(); bal != 900 {
619			t.Fatalf("treasury=%d", bal)
620		}
621		// 已执行提案不退回通过；重试返回首次凭据。
622		again, err := store.Execute("gip-exec", 99999)
623		if err != nil || again.ExecutedAt != 300 {
624			t.Fatalf("retry execute: %+v err=%v", again, err)
625		}
626		v, _, _ := store.VoteProposal("gip-exec")
627		if v.State != "executed" {
628			t.Fatalf("state=%s", v.State)
629		}
630		store.Close()
631	
632		// 重开后状态完整、结论保留。
633		reopened, err := Open(path)
634		if err != nil {
635			t.Fatalf("reopen: %v", err)
636		}
637		defer reopened.Close()
638		v2, ok, err := reopened.VoteProposal("gip-exec")
639		if err != nil || !ok || v2.State != "executed" || v2.Tally == nil || !v2.Tally.Passed {
640			t.Fatalf("reopened view: %+v ok=%v err=%v", v2, ok, err)
641		}
642		if r, ok, _ := reopened.Receipt("gip-exec"); !ok || r.ExecutedAt != 300 {
643			t.Fatalf("receipt after reopen: %+v %v", r, ok)
644		}
645	
646		// rejected 的投票提案不能执行。
647		bad, _ := openTempStore(t, 100)
648		defer bad.Close()
649		in2 := baseVoteInput("gip-rej")
650		mustCreateVote(t, bad, in2)
651		if _, err := bad.CastVote("gip-rej", "dave", false, 150); err != nil {
652			t.Fatal(err)
653		}
654		if _, err := bad.TallyVote("gip-rej", 200); err != nil {
655			t.Fatal(err)
656		}
657		if _, err := bad.Execute("gip-rej", 300); !errors.Is(err, ErrExecutionRejected) {
658			t.Fatalf("execute rejected proposal: %v", err)
659		}
660	}
